package com.company.platform.order.infrastructure;
import jakarta.servlet.*;import jakarta.servlet.http.HttpServletRequest;import jakarta.servlet.http.HttpServletResponse;import org.slf4j.MDC;import org.springframework.stereotype.Component;import java.io.IOException;import java.util.UUID;
@Component public class CorrelationIdFilter implements Filter{public void doFilter(ServletRequest req,ServletResponse res,FilterChain chain)throws IOException,ServletException{String id=((HttpServletRequest)req).getHeader("X-Correlation-Id");if(id==null||id.isBlank())id=UUID.randomUUID().toString();MDC.put("correlationId",id);((HttpServletResponse)res).setHeader("X-Correlation-Id",id);try{chain.doFilter(req,res);}finally{MDC.remove("correlationId");}}}
